const findFeedCandidatesFallback = `-- name: FindFeedCandidatesFallback :many
SELECT u.id, u.email, u.profile_validated, u.is_premium,
       p.first_name, p.username, p.avatar_url, p.profile_picture_url, p.is_online, p.last_seen_at,
       d.birth_date, d.gender, d.city_id, d.city_name
FROM users u
JOIN profiles p ON u.id = p.user_id
JOIN demographics d ON u.id = d.user_id
WHERE u.id != $1
  AND u.profile_validated = true
  AND (u.banned_until IS NULL OR u.banned_until < CURRENT_TIMESTAMP)
  AND d.gender = $2
  AND (p.avatar_url != '' OR p.profile_picture_url IS NOT NULL OR EXISTS (SELECT 1 FROM user_galleries ug WHERE ug.user_id = u.id))
ORDER BY p.is_online DESC, p.last_seen_at DESC, u.id ASC
LIMIT $3
`

type FindFeedCandidatesFallbackParams struct {
	ID     int32  `json:"id"`
	Gender Gender `json:"gender"`
	Limit  int32  `json:"limit"`
}

type FindFeedCandidatesFallbackRow struct {
	ID                int32            `json:"id"`
	Email             string           `json:"email"`
	ProfileValidated  bool             `json:"profile_validated"`
	IsPremium         bool             `json:"is_premium"`
	FirstName         string           `json:"first_name"`
	Username          pgtype.Text      `json:"username"`
	AvatarUrl         string           `json:"avatar_url"`
	ProfilePictureUrl pgtype.Text      `json:"profile_picture_url"`
	IsOnline          bool             `json:"is_online"`
	LastSeenAt        pgtype.Timestamp `json:"last_seen_at"`
	BirthDate         pgtype.Date      `json:"birth_date"`
	Gender            Gender           `json:"gender"`
	CityID            pgtype.Int4      `json:"city_id"`
	CityName          pgtype.Text      `json:"city_name"`
}

// Fallback feed candidates (excluding only self)
func (q *Queries) FindFeedCandidatesFallback(ctx context.Context, arg FindFeedCandidatesFallbackParams) ([]FindFeedCandidatesFallbackRow, error) {
	rows, err := q.db.Query(ctx, findFeedCandidatesFallback, arg.ID, arg.Gender, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []FindFeedCandidatesFallbackRow
	for rows.Next() {
		var i FindFeedCandidatesFallbackRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.ProfileValidated,
			&i.IsPremium,
			&i.FirstName,
			&i.Username,
			&i.AvatarUrl,
			&i.ProfilePictureUrl,
			&i.IsOnline,
			&i.LastSeenAt,
			&i.BirthDate,
			&i.Gender,
			&i.CityID,
			&i.CityName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

